-- Reviews: only for delivered orders (trigger review_only_after_delivery).

-- End state: a few unavailable dishes, one closed restaurant, partners with live orders are busy.
UPDATE menu_items SET is_available = FALSE WHERE item_id IN (54, 66, 45, 56, 7, 73, 5, 83);
UPDATE restaurants SET is_open = FALSE WHERE restaurant_id = 12;
UPDATE delivery_partners SET status = 'busy' WHERE partner_id IN (7, 8, 9, 11, 12, 13, 15, 16);

-- The trigger stamps delivered_at = now(); back-date it so dashboards show realistic history.
SET CONSTRAINTS ALL IMMEDIATE;   -- run deferred checks now (ALTER TABLE is blocked while they are pending)
ALTER TABLE orders DISABLE TRIGGER order_status_transition;
UPDATE orders SET delivered_at = placed_at + (30 + (order_id * 7) % 31) * INTERVAL '1 minute'
 WHERE status = 'delivered';
ALTER TABLE orders ENABLE TRIGGER order_status_transition;

-- Keep SERIAL sequences ahead of the explicit ids used above.
SELECT setval(pg_get_serial_sequence('users', 'user_id'), (SELECT MAX(user_id) FROM users));
SELECT setval(pg_get_serial_sequence('restaurants', 'restaurant_id'), (SELECT MAX(restaurant_id) FROM restaurants));
SELECT setval(pg_get_serial_sequence('menu_items', 'item_id'), (SELECT MAX(item_id) FROM menu_items));
SELECT setval(pg_get_serial_sequence('orders', 'order_id'), (SELECT MAX(order_id) FROM orders));
SELECT setval(pg_get_serial_sequence('payments', 'payment_id'), (SELECT MAX(payment_id) FROM payments));
SELECT setval(pg_get_serial_sequence('cuisines', 'cuisine_id'), (SELECT MAX(cuisine_id) FROM cuisines));

COMMIT;
